script:
(function () {
  'use strict';

  function $(id) { return document.getElementById(id); }

  var deviceSelect = $('deviceSelect');
  var btnStart = $('btnStartMic');
  var btnStop = $('btnStopMic');
  var checkRawAudio = $('checkRawAudio');
  var diagnosticPanel = $('diagnosticPanel');
  var peakFill = $('peakFill');
  var peakHoldTick = $('peakHoldTick');
  var peakBand = $('peakBand');
  var peakReadout = $('peakReadout');
  var peakScale = $('peakScale');
  var rmsFill = $('rmsFill');
  var rmsBand = $('rmsBand');
  var rmsReadout = $('rmsReadout');
  var rmsScale = $('rmsScale');
  var statPeak = $('statPeak');
  var statRms = $('statRms');
  var statClips = $('statClips');
  var statMin = $('statMin');
  var statAvg = $('statAvg');
  var statMax = $('statMax');
  var statSessionPeak = $('statSessionPeak');
  var infoHeadroom = $('infoHeadroom');
  var infoCrest = $('infoCrest');
  var infoClip = $('infoClip');
  var infoSpeech = $('infoSpeech');
  var infoGuide = $('infoGuide');
  var infoExposure = $('infoExposure');
  var infoOffset = $('infoOffset');
  var infoSettings = $('infoSettings');
  var clipLog = $('clipLog');
  var graphCanvas = $('graphCanvas');
  var graphCtx = graphCanvas.getContext('2d');
  var btnReset = $('btnReset');
  var selectGraph = $('selectGraph');
  var selectScale = $('selectScale');
  var selectWeighting = $('selectWeighting');
  var selectRate = $('selectRate');
  var selectPeakHold = $('selectPeakHold');
  var calibrationSlider = $('calibrationSlider');
  var calibrationValue = $('calibrationValue');
  var referenceInput = $('referenceInput');
  var btnAlign = $('btnAlign');
  var btnResetCalibration = $('btnResetCalibration');
  var exposureRange = $('exposureRange');
  var exposureInput = $('exposureInput');
  var exposureNiosh = $('exposureNiosh');
  var exposureOsha = $('exposureOsha');

  var currentStream = null;
  var currentDeviceId = '';
  var starting = false;
  var audioCtx = null;
  var analyser = null;      // weighted signal -> RMS / spectrum
  var rawAnalyser = null;   // unweighted signal -> true sample peak / clipping
  var source = null;
  var weightingNodes = [];
  var rafId = null;
  var floatData = null, rawFloat = null, byteData = null, rawByte = null, freqBytes = null;

  var peakHoldDb = -120;
  var peakHoldUntil = 0;
  var clipCount = 0;
  var lastClipTime = 0;
  var sessionStartTime = 0;

  // Display-interval accumulators
  var accSq = 0, accN = 0, accPeak = -120, lastDisplay = 0;
  // Session statistics (all in dBFS of the weighted signal, except peak)
  var sesEnergy = 0, sesFrames = 0, sesMin = Infinity, sesMax = -Infinity, sesPeak = -120;
  // Graph history (one point per 100 ms)
  var history = [], histSq = 0, histN = 0, histStart = 0;

  var MIN_DB = -60;
  var SPL_BASE = 100; // positive scale = dBFS + 100 + calibration offset
  // -18 to -6 dBFS is a widely used conversational-speech target band for
  // a mic level meter -- loud enough to sit well above the noise floor,
  // with headroom before clipping.
  var BAND_LOW = -18, BAND_HIGH = -6;
  // Anything within 1dB of full scale counts as clipping for this meter's
  // purposes -- true 0dBFS is vanishingly rare to land on exactly.
  var CLIP_THRESHOLD_DB = -1;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function offset() { return parseFloat(calibrationSlider.value) || 0; }
  function isSpl() { return selectScale.value === 'spl'; }
  function toDisplay(db) { return isSpl() ? db + SPL_BASE + offset() : db; }
  function unit() {
    var w = selectWeighting.value;
    if (isSpl()) return w === 'Z' ? 'dB' : 'dB' + w;
    return w === 'Z' ? 'dBFS' : 'dBFS(' + w + ')';
  }
  function fmt(db, decimals) {
    if (!isFinite(db) || db <= -120) return '—';
    return toDisplay(db).toFixed(decimals == null ? 1 : decimals) + ' ' + unit();
  }

  function dbToPct(db) {
    var pct = ((db - MIN_DB) / (0 - MIN_DB)) * 100;
    return Math.max(0, Math.min(100, pct));
  }

  function positionBand(bandEl) {
    var left = dbToPct(BAND_LOW);
    var right = dbToPct(BAND_HIGH);
    bandEl.style.left = left + '%';
    bandEl.style.width = (right - left) + '%';
  }
  positionBand(peakBand);
  positionBand(rmsBand);

  function updateScales() {
    var marks = [-60, -40, -20, 0];
    var html = marks.map(function (m) { return '<span>' + (Math.round(toDisplay(m)) + '').replace('-', '−') + ' dB</span>'; }).join('');
    peakScale.innerHTML = html;
    rmsScale.innerHTML = html;
    var o = offset();
    infoOffset.textContent = isSpl() ? '+' + (SPL_BASE + o).toFixed(1) + ' dB (100 ' + (o < 0 ? '− ' : '+ ') + Math.abs(o).toFixed(1) + ')' : 'None (dBFS)';
    var rateOpt = selectRate.options[selectRate.selectedIndex];
    var holdOpt = selectPeakHold.options[selectPeakHold.selectedIndex];
    infoSettings.textContent = (isSpl() ? 'Est. dB SPL' : 'dBFS') + ', ' + selectWeighting.value + '-weighted, ' + rateOpt.textContent + ', hold ' + holdOpt.textContent + (checkRawAudio.checked ? ', processing off' : ', processing on');
  }

  function resizeCanvas() {
    var rect = graphCanvas.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    graphCanvas.width = Math.max(1, Math.round(rect.width * dpr));
    graphCanvas.height = Math.max(1, Math.round(rect.height * dpr));
  }

  function resetMeters() {
    peakFill.style.width = '0%';
    peakHoldTick.style.left = '0%';
    rmsFill.style.width = '0%';
    peakReadout.textContent = '— dB';
    rmsReadout.textContent = '— dB';
    statPeak.textContent = '—';
    statRms.textContent = '—';
    peakHoldDb = -120;
    peakHoldUntil = 0;
  }

  function resetSession() {
    clipCount = 0;
    lastClipTime = 0;
    statClips.textContent = '0';
    clipLog.innerHTML = '<div class="info-section-label">Recent Clipping (peak hit 0 dB)</div>';
    clipLog.classList.add('u-hidden');
    sesEnergy = 0; sesFrames = 0; sesMin = Infinity; sesMax = -Infinity; sesPeak = -120;
    history = []; histSq = 0; histN = 0;
    accSq = 0; accN = 0; accPeak = -120;
    var now = performance.now();
    sessionStartTime = now; histStart = now; lastDisplay = 0;
    peakHoldDb = -120; peakHoldUntil = 0;
    [statMin, statAvg, statMax, statSessionPeak].forEach(function (el) { el.textContent = '—'; });
    [infoHeadroom, infoCrest, infoClip, infoSpeech, infoExposure].forEach(function (el) { el.textContent = '—'; });
    infoGuide.textContent = isSpl() ? '—' : 'Switch to est. dB SPL';
    graphCtx.clearRect(0, 0, graphCanvas.width, graphCanvas.height);
  }

  function clearWeighting() {
    weightingNodes.forEach(function (n) { try { n.disconnect(); } catch (e) {} });
    weightingNodes = [];
  }

  // A/C frequency weighting built from first-order IIR sections (bilinear
  // transform, pre-warped to the standard IEC 61672 pole frequencies), then
  // normalised to 0 dB at 1 kHz. Z (flat) uses no filter.
  function connectWeighting() {
    if (!audioCtx || !source || !analyser) return;
    try { source.disconnect(analyser); } catch (e) {}
    clearWeighting();
    var type = selectWeighting.value;
    if (type === 'Z' || !audioCtx.createIIRFilter) {
      source.connect(analyser);
      return;
    }
    var fs = audioCtx.sampleRate, K = 2 * fs;
    function wc(f) { return 2 * fs * Math.tan(Math.PI * f / fs); }
    function hp(f) { var w = wc(f), d = K + w; return audioCtx.createIIRFilter([K / d, -K / d], [1, (w - K) / d]); }
    function lp(f) { var w = wc(f), d = K + w; return audioCtx.createIIRFilter([w / d, w / d], [1, (w - K) / d]); }
    var stages = [hp(20.598997), hp(20.598997), lp(12194.217), lp(12194.217)];
    if (type === 'A') stages.push(hp(107.65265), hp(737.86223));
    var f1k = new Float32Array([1000]), mag = new Float32Array(1), ph = new Float32Array(1), g = 1;
    stages.forEach(function (s) { s.getFrequencyResponse(f1k, mag, ph); g *= mag[0]; });
    var norm = audioCtx.createGain();
    norm.gain.value = g > 0 ? 1 / g : 1;
    source.connect(stages[0]);
    for (var i = 0; i < stages.length - 1; i++) stages[i].connect(stages[i + 1]);
    stages[stages.length - 1].connect(norm);
    norm.connect(analyser);
    weightingNodes = stages.concat([norm]);
  }

  function stopAnalysis() {
    if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
    clearWeighting();
    if (source) { try { source.disconnect(); } catch (e) {} source = null; }
    analyser = null;
    rawAnalyser = null;
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
  }

  // Every camera/mic page on this site copies this stopStream()/error
  // pattern from webcam-test-online.json (see this project's own
  // CLAUDE.md). This tool additionally tears down the AnalyserNode/
  // AudioContext and cancels the meter's rAF loop -- never left running
  // against a closed context.
  function stopStream() {
    stopAnalysis();
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    btnStop.disabled = true;
    btnReset.disabled = true;
    btnAlign.disabled = true;
    resetMeters();
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Microphone access was blocked.</strong> Click the camera icon in your address bar (or your browser’s site settings) and allow access, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No microphone was detected.</strong> Make sure a microphone is connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your microphone is already in use.</strong> Another app or browser tab is probably holding it — close video-calling apps or other audio tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This microphone doesn’t support the requested settings.</strong> Try a different microphone from the list above.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Microphone access requires a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The microphone request was interrupted. Click <strong>Start Microphone</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices) {
    var mics = devices.filter(function (d) { return d.kind === 'audioinput'; });
    deviceSelect.innerHTML = '';
    if (!mics.length) {
      var opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'No microphones found';
      deviceSelect.appendChild(opt);
      deviceSelect.disabled = true;
      return;
    }
    mics.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Microphone ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = false;
  }

  function refreshDeviceList() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(populateDeviceSelect).catch(function () {});
  }

  function readFloat(an, f32, u8) {
    if (an.getFloatTimeDomainData) { an.getFloatTimeDomainData(f32); return f32; }
    an.getByteTimeDomainData(u8);
    for (var i = 0; i < u8.length; i++) f32[i] = (u8[i] - 128) / 128;
    return f32;
  }

  function formatDuration(hours) {
    if (!isFinite(hours)) return '—';
    if (hours >= 24) return '24 h+';
    if (hours >= 1) {
      var h = Math.floor(hours), m = Math.round((hours - h) * 60);
      if (m === 60) { h++; m = 0; }
      return h + ' h' + (m ? ' ' + m + ' min' : '');
    }
    var mins = hours * 60;
    if (mins >= 1) return Math.round(mins) + ' min';
    return Math.max(1, Math.round(mins * 60)) + ' s';
  }
  function nioshHours(L) { return 8 / Math.pow(2, (L - 85) / 3); }
  function oshaHours(L) { return 8 / Math.pow(2, (L - 90) / 5); }

  function guideFor(spl) {
    if (spl < 30) return 'Very quiet (whisper, empty bedroom)';
    if (spl < 50) return 'Quiet (library, quiet office)';
    if (spl < 70) return 'Moderate (conversation, busy office)';
    if (spl < 85) return 'Loud (traffic, vacuum cleaner)';
    if (spl < 100) return 'Very loud (risk with long exposure)';
    return 'Dangerous (use hearing protection)';
  }

  function speechStatus(avg, peak) {
    if (sesFrames < 20) return '—';
    if (peak >= CLIP_THRESHOLD_DB) return 'Too hot — clipping; lower the input';
    if (avg < -30) return 'Too low — raise input or move closer';
    if (peak > -6 || avg > -18) return 'Hot — little headroom';
    return 'Good working level';
  }

  function updateSessionReadouts() {
    if (!sesFrames) return;
    var avg = 10 * Math.log10(sesEnergy / sesFrames);
    statMin.textContent = isFinite(sesMin) ? fmt(sesMin) : '—';
    statAvg.textContent = fmt(avg);
    statMax.textContent = isFinite(sesMax) ? fmt(sesMax) : '—';
    statSessionPeak.textContent = sesPeak > -120 ? sesPeak.toFixed(1) + ' dBFS' : '—';
    infoHeadroom.textContent = sesPeak > -120 ? (-sesPeak).toFixed(1) + ' dB' : '—';
    infoCrest.textContent = sesPeak > -120 ? (sesPeak - avg).toFixed(1) + ' dB' : '—';
    infoClip.textContent = clipCount ? 'CLIP — ' + clipCount + ' event' + (clipCount === 1 ? '' : 's') : 'No clipping';
    infoSpeech.textContent = speechStatus(avg, sesPeak);
    if (isSpl()) {
      var spl = toDisplay(avg);
      infoGuide.textContent = guideFor(spl);
      infoExposure.textContent = spl < 70 ? 'No practical limit' : formatDuration(nioshHours(spl)) + ' (NIOSH)';
    } else {
      infoGuide.textContent = 'Switch to est. dB SPL';
      infoExposure.textContent = 'Needs est. dB SPL';
    }
  }

  function drawGraph(currentDb) {
    var w = graphCanvas.width, h = graphCanvas.height;
    graphCtx.clearRect(0, 0, w, h);
    var mode = selectGraph.value;
    if (mode === 'history') {
      // Recommended band shading
      var yOf = function (db) { return h - (dbToPct(db) / 100) * h; };
      graphCtx.fillStyle = 'rgba(52,211,153,.14)';
      graphCtx.fillRect(0, yOf(BAND_HIGH), w, yOf(BAND_LOW) - yOf(BAND_HIGH));
      graphCtx.strokeStyle = 'rgba(0,0,0,.08)';
      graphCtx.lineWidth = 1;
      [-40, -20].forEach(function (db) { graphCtx.beginPath(); graphCtx.moveTo(0, yOf(db)); graphCtx.lineTo(w, yOf(db)); graphCtx.stroke(); });
      var n = 300;
      var pts = history.slice(-n);
      graphCtx.strokeStyle = '#7c5cff';
      graphCtx.lineWidth = Math.max(1.5, w / 500);
      graphCtx.beginPath();
      for (var i = 0; i < pts.length; i++) {
        var x = w - (pts.length - 1 - i) * (w / (n - 1));
        if (i === 0) graphCtx.moveTo(x, yOf(pts[i])); else graphCtx.lineTo(x, yOf(pts[i]));
      }
      graphCtx.stroke();
      return;
    }
    if (!analyser) return;
    analyser.getByteFrequencyData(freqBytes);
    var nyq = audioCtx.sampleRate / 2;
    graphCtx.fillStyle = '#7c5cff';
    if (mode === 'bars') {
      var bars = 32, bw = w / bars;
      for (var b = 0; b < bars; b++) {
        var f0 = 31.5 * Math.pow(2, b * 10 / bars), f1 = 31.5 * Math.pow(2, (b + 1) * 10 / bars);
        var i0 = Math.floor(f0 / nyq * freqBytes.length), i1 = Math.min(freqBytes.length - 1, Math.max(i0, Math.ceil(f1 / nyq * freqBytes.length)));
        var m = 0;
        for (var k = i0; k <= i1; k++) if (freqBytes[k] > m) m = freqBytes[k];
        var bh = m / 255 * h;
        graphCtx.fillRect(b * bw + 1, h - bh, Math.max(1, bw - 2), bh);
      }
    } else {
      var cols = Math.max(1, Math.round(w / 2));
      graphCtx.beginPath();
      graphCtx.moveTo(0, h);
      for (var c = 0; c < cols; c++) {
        var freq = 20 * Math.pow(1000, c / (cols - 1));
        var bin = Math.min(freqBytes.length - 1, Math.round(freq / nyq * freqBytes.length));
        graphCtx.lineTo(c * (w / (cols - 1)), h - freqBytes[bin] / 255 * h);
      }
      graphCtx.lineTo(w, h);
      graphCtx.closePath();
      graphCtx.fillStyle = 'rgba(124,92,255,.35)';
      graphCtx.fill();
      graphCtx.strokeStyle = '#7c5cff';
      graphCtx.stroke();
    }
  }

  function drawFrame() {
    rafId = requestAnimationFrame(drawFrame);
    if (!analyser) return;

    var data = readFloat(analyser, floatData, byteData);
    var raw = readFloat(rawAnalyser, rawFloat, rawByte);
    var sumSquares = 0, peakAbs = 0, i;
    for (i = 0; i < data.length; i++) sumSquares += data[i] * data[i];
    for (i = 0; i < raw.length; i++) { var a = Math.abs(raw[i]); if (a > peakAbs) peakAbs = a; }
    var ms = sumSquares / data.length;
    var rmsDb = ms > 0 ? 10 * Math.log10(ms) : -120;
    var peakDb = peakAbs > 0 ? 20 * Math.log10(peakAbs) : -120;
    var now = performance.now();

    // Session statistics. Min starts 1 s after measuring begins so the
    // device's start-up silence doesn't become the session minimum.
    sesEnergy += ms > 0 ? ms : 1e-12;
    sesFrames++;
    if (now - sessionStartTime > 1000 && rmsDb < sesMin) sesMin = Math.max(-120, rmsDb);
    if (rmsDb > sesMax) sesMax = rmsDb;
    if (peakDb > sesPeak) sesPeak = peakDb;

    // 100 ms graph history
    histSq += ms; histN++;
    if (now - histStart >= 100) {
      history.push(Math.max(MIN_DB, 10 * Math.log10(Math.max(1e-12, histSq / histN))));
      if (history.length > 600) history.shift();
      histSq = 0; histN = 0; histStart = now;
    }

    // Display-rate integration: readouts and bars show the energy average
    // over the chosen update interval (time weighting), not one frame.
    accSq += ms; accN++; if (peakDb > accPeak) accPeak = peakDb;
    var interval = parseInt(selectRate.value, 10) || 0;
    if (now - lastDisplay >= interval) {
      var dispRms = 10 * Math.log10(Math.max(1e-12, accSq / accN));
      var dispPeak = accPeak;
      accSq = 0; accN = 0; accPeak = -120; lastDisplay = now;

      rmsFill.style.width = dbToPct(dispRms) + '%';
      rmsReadout.textContent = fmt(Math.max(-120, dispRms), 0);
      statRms.textContent = fmt(Math.max(-120, dispRms), 0);
      peakFill.style.width = dbToPct(dispPeak) + '%';
      peakReadout.textContent = dispPeak > -120 ? Math.round(dispPeak) + ' dBFS' : '— dB';
      statPeak.textContent = dispPeak > -120 ? Math.round(dispPeak) + ' dBFS' : '—';
      updateSessionReadouts();
    }

    // Peak hold: hold for the chosen time (or forever), then decay.
    var holdSel = selectPeakHold.value;
    var holdMs = holdSel === 'inf' ? Infinity : parseInt(holdSel, 10);
    if (peakDb > peakHoldDb) {
      peakHoldDb = peakDb;
      peakHoldUntil = now + holdMs;
    } else if (now > peakHoldUntil) {
      peakHoldDb = Math.max(peakDb, peakHoldDb - 0.6, -120);
    }
    peakHoldTick.style.left = dbToPct(peakHoldDb) + '%';

    if (peakDb >= CLIP_THRESHOLD_DB && now - lastClipTime > 300) {
      clipCount++;
      statClips.textContent = String(clipCount);
      lastClipTime = now;
      var elapsedS = Math.round((now - sessionStartTime) / 1000);
      var mm = Math.floor(elapsedS / 60);
      var ss = String(elapsedS % 60).padStart(2, '0');
      var row = document.createElement('div');
      row.className = 'info-row';
      row.innerHTML = '<span class="info-label">' + mm + ':' + ss + ' into session</span><span class="info-value">Peak clipped</span>';
      clipLog.appendChild(row);
      clipLog.classList.remove('u-hidden');
      var rows = clipLog.querySelectorAll('.info-row');
      if (rows.length > 5) rows[0].remove();
    }

    drawGraph(rmsDb);
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting microphone access…' }]);
    btnStart.disabled = true;

    var rawAudio = checkRawAudio.checked;
    var audioConstraint = {
      autoGainControl: !rawAudio,
      echoCancellation: !rawAudio,
      noiseSuppression: !rawAudio,
    };
    if (deviceId) audioConstraint.deviceId = { exact: deviceId };

    navigator.mediaDevices.getUserMedia({ audio: audioConstraint, video: false })
      .then(function (stream) {
        currentStream = stream;
        var track = stream.getAudioTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        currentDeviceId = settings.deviceId || deviceId || '';

        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        audioCtx.resume().catch(function () {});
        analyser = audioCtx.createAnalyser();
        analyser.fftSize = 2048;
        analyser.smoothingTimeConstant = 0.6;
        rawAnalyser = audioCtx.createAnalyser();
        rawAnalyser.fftSize = 2048;
        floatData = new Float32Array(analyser.fftSize);
        rawFloat = new Float32Array(rawAnalyser.fftSize);
        byteData = new Uint8Array(analyser.fftSize);
        rawByte = new Uint8Array(rawAnalyser.fftSize);
        freqBytes = new Uint8Array(analyser.frequencyBinCount);
        source = audioCtx.createMediaStreamSource(stream);
        // Deliberately never connected to audioCtx.destination -- routing
        // a live mic to speakers without a hard opt-in creates a feedback
        // loop (same safety rule as microphone-test-online.json).
        source.connect(rawAnalyser);
        connectWeighting();
        resizeCanvas();
        resetSession();
        updateScales();

        btnStop.disabled = false;
        btnReset.disabled = false;
        btnAlign.disabled = false;
        var notes = [{ sev: 'ok', html: '<strong>Microphone is live.</strong> Speak normally and watch the two meters — nothing is recorded or uploaded.' }];
        if (rawAudio && settings.autoGainControl === true) {
          notes.push({ sev: 'warn', html: 'Your browser kept <strong>auto gain control on</strong> despite the request, so levels may still drift.' });
        }
        if (selectWeighting.value !== 'Z' && !audioCtx.createIIRFilter) {
          notes.push({ sev: 'warn', html: 'This browser can’t apply A/C weighting; readings are flat (Z).' });
        }
        setDiagnostic(notes);
        drawFrame();
        return refreshDeviceList();
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
        stopStream();
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  function updateCalibrationLabel() {
    var o = offset();
    calibrationValue.textContent = (o > 0 ? '+' : '') + o.toFixed(1) + ' dB';
    updateScales();
    updateSessionReadouts();
  }

  function updateExposure(val) {
    var L = parseFloat(val);
    if (!isFinite(L)) return;
    L = Math.max(70, Math.min(130, L));
    exposureNiosh.textContent = formatDuration(nioshHours(L));
    exposureOsha.textContent = formatDuration(oshaHours(L));
  }

  // ---- Events ---------------------------------------------------------------
  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Microphone stopped. Click <strong>Start Microphone</strong> to test again.' }]);
  });
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });
  checkRawAudio.addEventListener('change', function () {
    updateScales();
    if (currentStream) startStream(deviceSelect.value);
  });
  btnReset.addEventListener('click', function () { resetSession(); resetMeters(); });
  selectScale.addEventListener('change', function () { updateScales(); updateSessionReadouts(); });
  selectWeighting.addEventListener('change', function () {
    connectWeighting();
    updateScales();
    if (audioCtx) { resetSession(); }
  });
  selectRate.addEventListener('change', updateScales);
  selectPeakHold.addEventListener('change', function () { updateScales(); peakHoldUntil = 0; });
  selectGraph.addEventListener('change', function () { graphCtx.clearRect(0, 0, graphCanvas.width, graphCanvas.height); });
  calibrationSlider.addEventListener('input', updateCalibrationLabel);
  btnResetCalibration.addEventListener('click', function () { calibrationSlider.value = '0'; updateCalibrationLabel(); });
  btnAlign.addEventListener('click', function () {
    var ref = parseFloat(referenceInput.value);
    if (!isFinite(ref) || ref <= 0) { setDiagnostic([{ sev: 'warn', html: 'Enter the reference meter average first.' }]); referenceInput.focus(); return; }
    if (!sesFrames) { setDiagnostic([{ sev: 'warn', html: 'Run the meter for a few seconds first.' }]); return; }
    var avg = 10 * Math.log10(sesEnergy / sesFrames);
    var o = ref - (avg + SPL_BASE);
    var clamped = Math.max(-30, Math.min(30, o));
    calibrationSlider.value = clamped.toFixed(1);
    selectScale.value = 'spl';
    updateCalibrationLabel();
    setDiagnostic([{ sev: Math.abs(o) > 30 ? 'warn' : 'ok', html: Math.abs(o) > 30
      ? '<strong>Offset limited to ' + clamped.toFixed(1) + ' dB.</strong> The reference needs ' + o.toFixed(1) + ' dB, outside the ±30 dB range — check the input level and that both meters measured the same sound.'
      : '<strong>Aligned.</strong> Offset set to ' + clamped.toFixed(1) + ' dB, so this session’s average now reads ' + ref.toFixed(1) + ' dB. Valid only for this mic and input setting.' }]);
  });
  exposureRange.addEventListener('input', function () { exposureInput.value = exposureRange.value; updateExposure(exposureRange.value); });
  exposureInput.addEventListener('input', function () {
    var v = parseFloat(exposureInput.value);
    if (isFinite(v)) exposureRange.value = String(Math.max(70, Math.min(130, v)));
    updateExposure(exposureInput.value);
  });
  window.addEventListener('resize', resizeCanvas);

  // Guaranteed teardown: release the microphone and tear down the audio
  // graph the moment the visitor leaves this page, even if they never
  // clicked Stop.
  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  updateScales();
  updateExposure(exposureInput.value);
  resizeCanvas();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support microphone access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  }
})();
